create table if not exists projects(id text primary key,name text not null,description text not null default '',status text not null default 'active',portfolio text not null default 'Core',start_date date,end_date date,tag text not null default '');
create table if not exists tasks(id text primary key,project_id text not null references projects(id) on delete cascade,title text not null,description text not null default '',status text not null default 'planned',priority text not null default 'normal',start_date date,eta date,actual_end_date date,planned_week text not null default '',spillover boolean not null default false,personal boolean not null default false);
create table if not exists subtasks(id text primary key,task_id text not null references tasks(id) on delete cascade,project_id text not null references projects(id) on delete cascade,title text not null,description text not null default '',status text not null default 'planned',priority text not null default 'normal',scheduled_date date,effort numeric not null default 1,carry_forward integer not null default 0,completed_date date,dependency_id text references subtasks(id));
create table if not exists daily_plans(id text primary key,date date not null,sprint_month text not null,selected_ids jsonb not null default '[]',selection jsonb not null default '[]',rationale text not null default '',planned_hours numeric not null default 0,candidate_count integer not null default 0,generated_at timestamptz not null default now());
create table if not exists planning_snapshots(id bigserial primary key,snapshot_date date not null,captured_at timestamptz not null default now(),projects jsonb not null,tasks jsonb not null,subtasks jsonb not null,source text not null);
create table if not exists sprint_plan_versions(id text primary key,sprint_month text not null,version integer not null,created_at timestamptz not null default now(),items jsonb not null default '[]',planned_hours numeric not null default 0,planned_subtasks integer not null default 0,unique(sprint_month,version));
create table if not exists capacity(id text primary key,date date not null unique,available_hours numeric not null default 7,reason text not null default '');
create index if not exists subtasks_scheduled_idx on subtasks(scheduled_date);
create index if not exists subtasks_task_idx on subtasks(task_id);
create index if not exists tasks_project_idx on tasks(project_id);
